// Package docs embeds the generated specifications and the Swagger UI page.
// swagger.json and swagger.yaml are generated by make docs; do not edit them by hand.
package docs

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"html/template"
	"io/fs"
	"strings"

	swaggerFiles "github.com/swaggo/files/v2"
)

//go:embed swagger.json
var OpenAPIJSON []byte

//go:embed swagger.yaml
var OpenAPIYAML []byte

//go:embed documentation.html
var documentationTemplate string

// Documentation includes all assets and the specification in one HTML response.
var Documentation = renderDocumentation()

func renderDocumentation() []byte {
	asset := func(name string) string {
		data, err := fs.ReadFile(swaggerFiles.FS, name)
		if err != nil {
			panic(fmt.Errorf("read embedded Swagger UI asset: %w", err))
		}
		return string(data)
	}
	// Avoid a separate source-map request when browser developer tools are open.
	css, _, _ := strings.Cut(asset("swagger-ui.css"), "/*# sourceMappingURL=")
	page := template.Must(template.New("documentation").Parse(documentationTemplate))
	var html bytes.Buffer
	err := page.Execute(&html, struct {
		CSS        template.CSS
		JavaScript template.JS
		Spec       json.RawMessage
	}{
		// Only the pinned, embedded library assets bypass template escaping.
		CSS:        template.CSS(css),
		JavaScript: template.JS(asset("swagger-ui-bundle.js")),
		Spec:       json.RawMessage(OpenAPIJSON),
	})
	if err != nil {
		panic(fmt.Errorf("render embedded API documentation: %w", err))
	}
	return html.Bytes()
}
